head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[ModelUtil > M > copyChildrenNodes]<br/>srcXPath 파라미터의 하위 노드들을 destXPath 파라미터의 하위 노드들로 복사합니다.",
    "validation" : [
        "srcXPath(필수) 파라미터로 복사할 소스 노드의 XPath 를 설정할 수 있어야 합니다.",
        "destXPath(필수) 파라미터로 복사 대상 노드의 XPath 를 설정할 수 있어야 합니다.",
        "mode(필수) 파라미터로 복사 모드를 설정할 수 있어야 합니다.",
        "mode='replaceAll' : destXPath 파라미터 노드의 모든 하위 노드를 제거하고 srcXPath 파라미터의 하위 노드로 교체해야 합니다.",
        "mode='overwrite' : srcXPath 와 destXPath 파라미터의 하위 노드를 이름 기준으로 매칭하여 교체해야 합니다. 매칭되지 않는 srcXPath 파라미터의 노드는 destXPath 파라미터의 노드에 추가되고, destXPath 파라미터에만 있는 노드는 유지되어야 합니다.",
        "mode='replaceOnly' : destXPath 파라미터의 하위 노드 중 srcXPath 파라미터에도 동일 이름이 있는 것만 교체해야 합니다. srcXPath 파라미터에만 있는 노드는 추가하지 않아야 합니다.",
        "mode='append' : srcXPath 파라미터의 하위 노드들을 destXPath 파라미터의 하위 노드에 그대로 추가해야 합니다. 기존 destXPath 파라미터의 하위 노드는 유지되어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 시나리오 실행 전 instance 원본 보존용 스냅샷
    scwin._origBookstore = WebSquare.xml.serialize(WebSquare.ModelUtil.findInstanceNode("bookstore"));
    scwin._origSelectedBook = WebSquare.xml.serialize(WebSquare.ModelUtil.findInstanceNode("selectedBook"));
};



// 특정 instance 노드를 원본 직렬화 문자열로 복원 (자식만 교체하여 wrap 중첩 방지)
scwin._resetNodeFromOrigin = function (xpath, origSerialized) {
    var instNode = WebSquare.ModelUtil.findInstanceNode(xpath);
    if (!instNode) return;
    while (instNode.firstChild) instNode.removeChild(instNode.firstChild);
    var origNode = WebSquare.xml.parse(origSerialized).documentElement;
    for (var i = 0; i < origNode.childNodes.length; i++) {
        if (origNode.childNodes[i].nodeType === 1) {
            instNode.appendChild(origNode.childNodes[i].cloneNode(true));
        }
    }
};

// 매 시나리오 실행 전 instance 데이터 원본으로 복구
scwin.resetInstance = function () {
    scwin._resetNodeFromOrigin("bookstore", scwin._origBookstore);
    scwin._resetNodeFromOrigin("selectedBook", scwin._origSelectedBook);
};



// 특정 xpath 노드를 serialize 하여 한 줄 문자열로 반환 (출력용)
scwin.dumpXPath = function (xpath) {
    var node = WebSquare.ModelUtil.findInstanceNode(xpath);
    if (!node) return "(node not found)";
    var s = WebSquare.xml.serialize(node);
    return s.replace(/\s+/g, " ").replace(/>\s+</g, "><");
};



scwin.btn_copyChildrenNodes_onclick = function () {
    var scenario = par_scenario.getValue();
    scwin.resetInstance();

    if (scenario === "1") {
        // 시나리오 1 : mode='replaceAll'
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : mode='replaceAll' (selectedBook 자식 모두 제거 후 book[@idx='2'] 자식으로 교체) ──");
        wf_body_bottom.getObj("scwin").setReturnValue("복사 전 selectedBook : " + scwin.dumpXPath("selectedBook"));

        WebSquare.ModelUtil.copyChildrenNodes("bookstore/book[@idx='2']", "selectedBook", "replaceAll");

        wf_body_bottom.getObj("scwin").setReturnValue("복사 후 selectedBook : " + scwin.dumpXPath("selectedBook"));
    } else if (scenario === "2") {
        // 시나리오 2 : mode='overwrite'
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : mode='overwrite' (이름 매칭 교체 + 미매칭 src 추가 + dest 단독 유지) ──");
        wf_body_bottom.getObj("scwin").setReturnValue("복사 전 selectedBook : " + scwin.dumpXPath("selectedBook"));

        WebSquare.ModelUtil.copyChildrenNodes("bookstore/book[@idx='2']", "selectedBook", "overwrite");

        wf_body_bottom.getObj("scwin").setReturnValue("복사 후 selectedBook : " + scwin.dumpXPath("selectedBook"));
    } else if (scenario === "3") {
        // 시나리오 3 : mode='replaceOnly'
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : mode='replaceOnly' (이름 매칭 dest 노드만 교체, src 단독 노드는 미추가) ──");
        wf_body_bottom.getObj("scwin").setReturnValue("복사 전 selectedBook : " + scwin.dumpXPath("selectedBook"));

        WebSquare.ModelUtil.copyChildrenNodes("bookstore/book[@idx='2']", "selectedBook", "replaceOnly");

        wf_body_bottom.getObj("scwin").setReturnValue("복사 후 selectedBook : " + scwin.dumpXPath("selectedBook"));
    } else if (scenario === "4") {
        // 시나리오 4 : mode='append'
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 4 : mode='append' (기존 dest 자식 유지 + src 자식 그대로 추가) ──");
        wf_body_bottom.getObj("scwin").setReturnValue("복사 전 selectedBook : " + scwin.dumpXPath("selectedBook"));

        WebSquare.ModelUtil.copyChildrenNodes("bookstore/book[@idx='2']", "selectedBook", "append");

        wf_body_bottom.getObj("scwin").setReturnValue("복사 후 selectedBook : " + scwin.dumpXPath("selectedBook"));
    }
};
